-            if (nwritten != (ssize_t)(block->used-block->pos)) {
-                if (nwritten == 0) errno = EIO;
-                return -1;
-            }
-            count += nwritten;
+
+    listRewindTail(am->incr_aof_list, &li);
+
+    /* server.aof_fd != -1 means that AOF is open, then we must 
