 /* If an AOF exists in the manifest but not on the disk, we consider 
 * this to be a fatal error. */
if (ret == AOF_NOT_EXIST) ret = AOF_FAILED;

if (ret != AOF_OK && ret != AOF_EMPTY) {
    goto cleanup;
}
